using He_Thong_GYM.DAL;using He_Thong_GYM.Models;
namespace He_Thong_GYM.BLL;
public sealed class TaiSanBLL{private readonly TaiSanDAL _d=new();public Task<List<ThietBi>> LayThietBiAsync()=>_d.LayThietBiAsync();public Task<List<PhongTapModel>> LayPhongAsync()=>_d.LayPhongAsync();public Task<List<BaoTri>> LayBaoTriAsync()=>_d.LayBaoTriAsync();public Task TaoBaoTriAsync(int t,int n,string x,decimal c,DateTime? ngayDuKien){He_Thong_GYM.Helpers.AuthorizationPolicy.Require("Admin", "Quản lý", "Nhân viên");if(string.IsNullOrWhiteSpace(x)||c<0)throw new ArgumentException("Thông tin bảo trì không hợp lệ.");if(ngayDuKien.HasValue&&ngayDuKien.Value.Date<DateTime.Today)throw new ArgumentException("Ngày dự kiến hoàn tất không được ở quá khứ.");return _d.TaoBaoTriAsync(t,n,x.Trim(),c,ngayDuKien);}public Task HoanTatBaoTriAsync(int maBaoTri,int maNV,string? ghiChu=null){He_Thong_GYM.Helpers.AuthorizationPolicy.Require("Admin", "Quản lý", "Nhân viên");return _d.HoanTatBaoTriAsync(maBaoTri,maNV,ghiChu);}public Task CapNhatThietBiAsync(int maTB,int? maPhong,string tinhTrang){He_Thong_GYM.Helpers.AuthorizationPolicy.Require("Admin", "Quản lý");if(maTB<=0)throw new ArgumentException("Mã thiết bị không hợp lệ.");if(string.IsNullOrWhiteSpace(tinhTrang))throw new ArgumentException("Tình trạng không được để trống.");return _d.CapNhatThietBiAsync(maTB,maPhong,tinhTrang);}public Task CapNhatPhongTapAsync(int maPhong,int sucChua,string trangThai){He_Thong_GYM.Helpers.AuthorizationPolicy.Require("Admin", "Quản lý");if(maPhong<=0||sucChua<=0)throw new ArgumentException("Thông tin phòng tập không hợp lệ.");return _d.CapNhatPhongTapAsync(maPhong,sucChua,trangThai);}}
